"""Small, dependency-free presentation and JSON utilities."""
import json
import math
import os
import re
import sys

RESET = '\x1b[0m'

def ansi(code, text):
    return '\x1b[' + str(code) + 'm' + str(text) + RESET

UNKNOWN = ansi('1;38;2;255;135;22', '??? >')
ERROR = ansi('1;31', '??? >')

def panic(location, message):
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at {location}:\n{message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    raise SystemExit(101)

def number_text(x):
    if isinstance(x, int):
        return str(x)
    s = repr(x)
    # serde's JSON number representation uses compact exponent digits.
    s = re.sub(r'e([+-])0+(\d+)', r'e\1\2', s)
    if 'e' in s and s.split('e')[0].endswith('.0'):
        s = s.replace('.0e', 'e')
    return s

def json_text(v):
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (int, float)):
        return number_text(v)
    if isinstance(v, str):
        return json.dumps(v, ensure_ascii=False, separators=(',', ':'))
    if isinstance(v, list):
        return '[' + ','.join(json_text(x) for x in v) + ']'
    if isinstance(v, dict):
        return '{' + ','.join(json_text(k)+':'+json_text(v[k]) for k in sorted(v)) + '}'
    return 'null'

def scalar(v):
    if isinstance(v, str):
        return v
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (int, float)):
        return number_text(v)
    return None

def render_value(v):
    """Unescaped template value rendering (different from JSON rendering)."""
    if v is None:
        return ''
    if isinstance(v, dict):
        return '[object]'
    if isinstance(v, list):
        return '[' + ', '.join(render_value(x) for x in v) + ']'
    return scalar(v) or ''

def truth(v, include_zero=False):
    if v is None or v is False:
        return False
    if isinstance(v, (dict, list, str)):
        return bool(v)
    if isinstance(v, (int, float)):
        return include_zero or v != 0
    return True
