            tokens.append(Subexpression(tokenize(s[start:i-1])))
        elif s[i] in '\"\'':
            q = s[i]; start = i; i += 1
            chars = []
            while i < len(s) and s[i] != q:
                if s[i] == '\\' and i+1 < len(s):
                    nxt=s[i+1]
