    def convert(v,in_array=False):
        if isinstance(v,dict) and not in_array:
            return '{'+','.join(norm(k)+' = '+convert(v[k]) for k in sorted(v))+'}'
        if isinstance(v,list) and not in_array:return '{'+','.join(convert(x,True) for x in v)+'}'
        if v is None or isinstance(v,(dict,list)):return '"unsupported"'
