        else:data=fallback_toml(text)
        for k,expected in DEFAULTS.items():
            if k not in data:continue
            v=data[k]
            good=(isinstance(v,type(expected)))
            if isinstance(expected,list):good=good and all(isinstance(x,str) for x in v)
            if isinstance(expected,dict):good=good and all(isinstance(x,str) for x in v.values())
