"""Command-line grammar and diagnostics."""
import os
import sys
import zipfile

OPTIONS=[
 ('additional-value','a',True,True),('config-file',None,True,False),
 ('message-key','m',True,True),('print-lua',None,False,False),
 ('time-key','t',True,True),('level-key','l',True,True),
 ('map-level',None,True,True),('dump-all','d',False,False),
 ('excluded-value','x',True,True),('with-prefix','p',False,False),
 ('filter','f',True,False),('no-implicit-filter-return-statement',None,False,False),
 ('main-line-format',None,True,False),('additional-value-format',None,True,False),
 ('substitute','s',False,False),('context-key','c',True,False),
 ('placeholder-format','F',True,False),('help','h',False,False),('version','V',False,False)
]
LONG={o[0]:o for o in OPTIONS};SHORT={o[1]:o for o in OPTIONS if o[1]}

def label(name):
    opt=LONG[name]
    return '--'+name+(' <'+('from=to' if name=='map-level' else name)+'>' if opt[2] else '')

def failure(message,usage=True,tip=None,used=None):
    sys.stderr.write('error: '+message+'\n\n')
    if tip:sys.stderr.write(tip+'\n\n')
    if usage:
        sys.stderr.write('Usage: executable'+(' '+' '.join(label(n) for n in used) if used else ' [OPTIONS]')+' [INPUT]\n\n')
    sys.stderr.write("For more information, try '--help'.\n")
    raise SystemExit(2)

def help_text():
    try:
        import importlib.resources
        # Running both from the source tree and from the single-file archive.
        p=os.path.join(os.path.dirname(__file__),'help.txt')
        with open(p,encoding='utf-8') as f:return f.read()
    except (OSError,NotADirectoryError):
        with zipfile.ZipFile(sys.argv[0]) as z:return z.read('help.txt').decode()

def parse(args):
    result={n:[] if repeat else False if not value else None for n,sh,value,repeat in OPTIONS};result['input']='-'
    positional=False;seen=[];i=0;end=False
    while i<len(args):
        a=args[i];i+=1
        if a=='--' and not end:end=True;continue
        if end or a=='-' or not a.startswith('-'):
            if positional:failure("unexpected argument '"+a+"' found")
            result['input']=a;positional=True;continue
        pending=[]
        if a.startswith('--'):
            n,eq,value=a[2:].partition('=')
            if n not in LONG:
                tip="  tip: to pass '"+a+"' as a value, use '-- "+a+"'"
                failure("unexpected argument '"+a+"' found",tip=tip)
            opt=LONG[n];pending=[(opt,value if eq else None)]
        else:
            j=1
            while j<len(a):
                c=a[j];j+=1
                if c not in SHORT:
                    flag='-'+c
                    failure("unexpected argument '"+flag+"' found",tip="  tip: to pass '"+flag+"' as a value, use '-- "+flag+"'")
                opt=SHORT[c];v=None
                if opt[2] and j<len(a):v=a[j:];v=v[1:] if v.startswith('=') else v;j=len(a)
                pending.append((opt,v))
                if opt[2]:break
        for opt,value in pending:
            n,short,takes,repeat=opt
            if n=='help':sys.stdout.write(help_text());raise SystemExit(0)
            if n=='version':sys.stdout.write('fblog 4.17.0\n');raise SystemExit(0)
            if n in seen and not repeat:failure("the argument '"+label(n)+"' cannot be used multiple times")
            if not takes and value is not None:
                failure("unexpected value '"+value+"' for '"+label(n)+"' found; no more were expected",usage=False)
            if takes and value is None:
                if i>=len(args) or args[i].startswith('--') or args[i] in ('-h','-V'):
                    failure("a value is required for '"+label(n)+"' but none was supplied",usage=False)
                if args[i].startswith('-') and args[i]!='-':
                    flag=args[i][:2] if not args[i].startswith('--') else args[i]
                    failure("unexpected argument '"+flag+"' found",tip="  tip: to pass '"+flag+"' as a value, use '-- "+flag+"'")
                value=args[i];i+=1
            if n=='map-level' and '=' not in value:failure("invalid value '"+value+"' for '--map-level <from=to>': missing '='",usage=False)
            if repeat:result[n].append(value)
            else:result[n]=value if takes else True
            if n not in seen:seen.append(n)
    if result['additional-value'] and result['excluded-value']:
        first='additional-value' if seen.index('additional-value')<seen.index('excluded-value') else 'excluded-value'
        second='excluded-value' if first=='additional-value' else 'additional-value'
        used=[n for n in seen if n not in (second,'help','version')]
        failure("the argument '"+label(first)+"' cannot be used with '"+label(second)+"'",used=used)
    return result
